<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../services/api';import type{AuditEvent,Classification}from'../types/archive';const classes=ref<Classification[]>([]),audits=ref<AuditEvent[]>([]),stats=ref<any>({});onMounted(async()=>{classes.value=(await api.get('/classifications')).data.items;audits.value=(await api.get('/audits')).data.items;stats.value=(await api.get('/admin/stats')).data})</script>
<template><div><el-row :gutter="16"><el-col :span="6"><el-statistic title="案卷总数" :value="stats.total_cases||0"/></el-col><el-col :span="6"><el-statistic title="已归档" :value="stats.archived_cases||0"/></el-col><el-col :span="6"><el-statistic title="待审批借阅" :value="stats.pending_borrows||0"/></el-col><el-col :span="6"><el-statistic title="审计事件" :value="stats.audit_events||0"/></el-col></el-row><el-row :gutter="16" class="panels"><el-col :span="9"><el-card><template #header><b>分类树</b></template><el-tree :data="classes" node-key="id" :props="{label:'name'}" draggable/></el-card></el-col><el-col :span="15"><el-card><template #header><b>审计时间线</b></template><el-timeline><el-timeline-item v-for="a in audits" :key="a.id" :timestamp="a.created_at">{{a.action}} · {{a.resource}}/{{a.resource_id}}<small> request_id={{a.request_id}}</small></el-timeline-item></el-timeline></el-card></el-col></el-row></div></template><style scoped>.panels{margin-top:18px}small{color:#8492a6;margin-left:8px}</style>
